function advance(s,minutes,interrupt=false){if(!Number.isInteger(minutes)||minutes<0||minutes>525600)throw Error('시간 범위 오류');const target=s.time+minutes;let processed=0;while(s.queue.length&&s.queue[0].at<=target&&!s.ending){if(++processed>20000)throw Error('예약 사건 한도 초과');const e=s.queue.shift();s.time=e.at;const last=s.journal.length;event(s,e);if(interrupt&&s.journal.slice(last).some(x=>x.type==='warning'||x.type==='collapse'))return {interrupted:true,remaining:target-s.time};}if(!s.ending)s.time=target;return{interrupted:false,remaining:0};}
