function rollTurn(s){const b=s.battle;if(!b)return;b.turn++;const st=stats(s);const n=b.training&&b.exercise===2?2:s.player.realm;b.playerSpeeds=Array.from({length:n},()=>st.minSpeed+Math.floor(rand(s,'combat')*(st.maxSpeed-st.minSpeed+1)));b.enemyActions=Array.from({length:b.enemy.slots},(_,i)=>({id:i,speed:1+Math.floor(rand(s,'combat')*5),target:i%n,base:b.training?(b.exercise===0?0:b.exercise===2?9:3):4,coins:b.training&&b.exercise===0?0:2,name:b.training?'훈련 인형의 공격':'갈라진 발톱'}));b.plans=Array.from({length:n},()=>({skill:'basic',target:0,clash:false}));}
function validatePlans(s,plans){const b=s.battle;if(!b||b.finished)throw Error('계획 가능한 전투 없음');if(plans.length!==b.playerSpeeds.length)throw Error('행동 슬롯 수 불일치');let total=0,heals=0;const used={},linked=new Set();for(let i=0;i<plans.length;i++){const p=plans[i],sk=D.skills[p.skill];if(!sk)throw Error('없는 기술');if(!sk.allowedWeaponFamilies.includes(s.player.weapon))throw Error('무기군 불일치');if(sk.discipline!=='common'&&(!s.player.deck.includes(sk.id)||sk.discipline!==s.player.discipline))throw Error('편성·계열 불일치');if(sk.requires&&!has(s,sk.requires))throw Error('전용 특성 필요');used[sk.id]=(used[sk.id]||0)+1;if(used[sk.id]>sk.limit)throw Error('기술의 턴당 사용 한도');if(p.clash){if(!Number.isInteger(p.target)||!b.enemyActions[p.target])throw Error('합 대상 없음');if(linked.has(p.target))throw Error('한 적 행동에는 한 합만 연결');const e=b.enemyActions[p.target];if(e.target!==i&&b.playerSpeeds[i]<=e.speed)throw Error('가로채기에는 더 빠른 속도 필요');linked.add(p.target);}if(sk.type==='heal')heals++;total+=cost(s,sk);}if(heals>s.player.potions)throw Error('회복제 부족');if(total>s.player.mp)throw Error('예약 MP 부족');return total;}
function power(s,sk,n,enemy=false,base){let val=base??sk.base;let growth=enemy||sk.discipline==='common'?0:Math.max(0,s.player.maxMp-40);val+=Math.floor(growth*.02)+(enemy?0:Math.floor(Math.min(1000,s.player.mastery[sk.id]||0)/100));let heads=0;for(let j=0;j<n;j++)if(rand(s,'combat')<.5)heads++;return {value:val+heads*(sk.coin+Math.floor(growth*.005)),heads};}
