function battleFinish(s){const b=s.battle;if(!b||!b.finished)throw Error('전투 진행 중');if(b.training){Object.assign(s.player,b.playerStart);if(!s.tutorial.completed.includes(b.exercise))s.tutorial.completed.push(b.exercise);journal(s,'tutorial',D.trainingGuide[b.exercise].title+' 훈련 완료. HP·MP·소모품 복원.');s.training++;s.battle=null;if(s.training>=4)s.prologue=4;return;}if(b.finished==='DEFEAT'){s.ending='HUNTER_LOST';s.battle=null;return;}const g=s.gates[b.gateId];if(g&&g.status!=='COLLAPSED'){g.status='CLEARED';s.player.money+=70;s.player.potions++;journal(s,'battle',`${b.gateId} 공략 완료. 보상 70크레딧·회복제 1개.`);publish(s,`서림 ${b.gateId} 게이트 공략 완료.`,b.gateId);}if(b.gateId==='first'){s.prologue=5;s.player.location='shop';}s.battle=null;checkEnd(s);}
function allowed(s,a){if(s.chapter!==1||s.district.collapsed||s.district.outcome||s.ending||s.battle)return '현재 진행 불가';if(s.flags[a.id])return '완료됨';if(a.effect==='medicine'&&s.flags.medicine)return '공급 확보됨';if(a.effect==='taeo'&&s.flags.taeo)return '태오의 상태 확정됨';if(a.effect==='team_rescue'&&(s.flags.taeo||s.team.status==='BUSY'))return '태오 구조 또는 지원팀 예약됨';if(a.effect==='team_gate'&&(s.team.status==='BUSY'||!Object.values(s.gates).some(g=>g.status==='OPEN')))return '지원팀/게이트 예약 확인';if(a.cost&&s.player.money<a.cost)return '크레딧 부족';if(a.id==='medicine_buy'&&s.market.stock<3)return '외부 재고 부족';return '';}
