function save(slot){if(!state)return;const str=E.serialize(state),base='bmh.v1.'+slot;const old=localStorage.getItem(base+'.current')||'A',next=old==='A'?'B':'A';localStorage.setItem(base+'.'+next,str);E.restore(localStorage.getItem(base+'.'+next));localStorage.setItem(base+'.current',next);}
